  "content": """"Compute domain scores from per-model item results and Pearson/Spearman vs visible targets."""
import json
import math
import itertools

LABELS = json.load(open('/workspace/whitebox.json'))['targets']
MODELS = ["development-01", "development-06", "development-08", "development-12"]


def pearson(xs, ys):
    n = len(xs)
    if n < 2:
        return None
    mx, my = sum(xs) / n, sum(ys) / n
    cov = sum((x - mx) * (y - my) for x, y in zip(xs, ys))
    vx = sum((x - mx) ** 2 for x in xs)
    vy = sum((y - my) ** 2 for y in ys)
    if vx == 0 or vy == 0:
        return None
    return cov / math.sqrt(vx * vy)


def spearman(xs, ys):
    def ranks(v):
        order = sorted(range(len(v)), key=lambda i: v[i])
        r = [0.0] * len(v)
        i = 0
        while i < len(v):
            j = i
            while j + 1 < len(v) and v[order[j + 1]] == v[order[i]]:
                j += 1
            avg = (i + j) / 2.0
            for k in range(i, j + 1):
                r[order[k]] = avg
            i = j + 1
        return r
    return pearson(ranks(xs), ranks(ys))


def domain_scores_from_items(items):
    """items: list of result dicts with id, score. Returns {domain: mean} using questions.json domains."""
    qs = json.load(open('/workspace/submission/assets/questions.json'))
    qd = {q['id']: q['domain'] for q in qs}
    by = {}
    for it in items:
        if it.get('score') is not None:
            by.setdefault(qd[it['id']], []).append(it['score'])
    return {d: sum(v) / len(v) for d, v in by.items()}


def evaluate(domain_scores_by_model, verbose=True):
    """domain_scores_by_model: {model: {domain: score}}"""
    target_corrs = {}
    domain_means = {}
    for tname, t in LABELS.items():
        dom = t['domain']
        scores = t['scores']
        common = [m for m in scores if m in domain_scores_by_model and dom in domain_scores_by_model[m]]
        xs = [domain_scores_by_model[m][dom] for m in common]
        ys = [scores[m] for m in common]
        p = pearson(xs, ys)
        s = spearman(xs, ys)
        target_corrs[tname] = {'pearson': p, 'spearman': s, 'n': len(common),
                               'measured': dict(zip(common, xs)), 'labels': scores}
        domain_means.setdefault(dom, []).append(p)
    macro = {}
    for d in ['coding', 'co-work', 'reasoning']:
        ps = [x for x in domain_means.get(d, []) if x is not None]
        macro[d] = sum(ps) / len(ps) if ps else None
    valid = [v for v in macro.values() if v is not None]
    objective = sum(valid) / len(valid) if valid else None
    if verbose:
        for tname, r in target_corrs.items():
            print(f"  {tname:24s} n={r['n']} pearson={fmt(r['pearson'])} spearman={fmt(r['spearman'])}")
        for d in ['coding', 'co-work', 'reasoning']:
            print(f"  DOMAIN {d:10s} mean-pearson={fmt(macro[d])}")
        print(f"  OBJECTIVE (3-domain macro) = {fmt(objective)}")
    return {'targets': target_corrs, 'domain_macro': macro, 'objective': objective}


def fmt(x):
    return f"{x:.3f}" if isinstance(x, float) else "None"


if __name__ == '__main__':
    import sys
    # args: json files with {"model":..., "items":[...]} or job output paths
    ds = {}
    for path in sys.argv[1:]:
        data = json.load(open(path))
        model = data['model']
        ds[model] = domain_scores_from_items(data['items'])
        print(model, json.dumps({d: round(s, 4) for d, s in ds[model].items()}))
    evaluate(ds)
"
}

